def on_native_closing():
    """Diffère la fermeture pour ne jamais bloquer la boucle graphique de macOS."""
    if EXIT_READY.is_set(): return True
    if UPDATE_BUSY.is_set(): return False
    if not NATIVE_CLOSE_LOCK.acquire(blocking=False): return False

    def prepare_close():
        try:
            answered = threading.Event()
            answer = []
            def receive(value):
                answer.append(value)
                answered.set()
            # dominisCanClose est asynchrone : attendre sa promesse via le callback
            # pywebview, hors du thread graphique (sinon blocage sur macOS).
            WINDOW.evaluate_js(
                'window.dominisCanClose ? window.dominisCanClose() : Promise.resolve(true)',
                callback=receive,
            )
            if not answered.wait(60):
                raise TimeoutError('L’interface ne répond pas. Réessayez de quitter.')
            if answer[0] is not True or EXIT_READY.is_set(): return
            sync_exit()
            EXIT_READY.set()
            WINDOW.destroy()
        except Exception as e:
            EXIT_READY.clear()
            print('Fermeture annulée : '+str(e), flush=True)
        finally:
            NATIVE_CLOSE_LOCK.release()

    threading.Thread(target=prepare_close, daemon=True).start()
    return False


def set_macos_identity():
    """Personnalise le Dock sans ajouter de dépendance au mode navigateur."""
    if sys.platform != 'darwin': return
    try:
        from AppKit import NSApplication, NSImage
        from Foundation import NSData, NSProcessInfo
        NSProcessInfo.processInfo().setProcessName_('Dominis')
        image = NSImage.alloc().initWithData_(NSData.dataWithBytes_length_(DOCK_ICON_PNG, len(DOCK_ICON_PNG)))
        if image is not None: NSApplication.sharedApplication().setApplicationIconImage_(image)
    except Exception as e:
        # Un souci cosmétique ne doit jamais empêcher l'accès aux données.
        print('Icône du Dock indisponible : '+str(e), flush=True)

def main():
    global DB,SERVER,WINDOW,PREVIEW,START_HOST,START_PORT,START_DESKTOP,START_NO_BROWSER
    global AUTO_SAVE_NOTICE, PRIMARY_DB_MISSING
    parser=argparse.ArgumentParser(description='Dominis — gestion locale multi-SCI')
    parser.add_argument('--db',default=str(ROOT/'data.db'));parser.add_argument('--port',type=int,default=8765)
    parser.add_argument('--host',default='127.0.0.1');parser.add_argument('--preview',action='store_true');parser.add_argument('--demo',action='store_true');parser.add_argument('--desktop',action='store_true');parser.add_argument('--no-browser',action='store_true')
    a=parser.parse_args();DB=Path(a.db).resolve();PREVIEW=a.preview
    START_HOST,START_PORT,START_DESKTOP,START_NO_BROWSER=a.host,a.port,a.desktop,a.no_browser
    EXIT_READY.clear()
    AUTO_SAVE_NOTICE = None
    PRIMARY_DB_MISSING = not PREVIEW and primary_db_has_recovery_copies()
    init_db()
    if a.demo: demo()
    if PRIMARY_DB_MISSING:
        AUTO_SAVE_NOTICE = {'error': True, 'message':
            'Le fichier principal data.db était absent. Dominis a créé une base vide et n’a pas ouvert les copies auto-save. '
            'Avant toute nouvelle saisie, utilisez Paramètres → Restaurer une sauvegarde.'}
    elif not PREVIEW:
        try:
            saved = maybe_create_weekly_auto_save()
            if saved:
                AUTO_SAVE_NOTICE = {'error': False, 'message': 'Sauvegarde hebdomadaire créée : ' + saved.name}
        except Exception as e:
            AUTO_SAVE_NOTICE = {'error': True, 'message': 'Sauvegarde hebdomadaire impossible : ' + str(e)}
            print(AUTO_SAVE_NOTICE['message'], flush=True)
    try: SERVER=DominisHTTPServer((a.host,a.port),Handler)
    except OSError:
        print('Port déjà utilisé. Fermez l’instance existante ou choisissez --port 8766.');return 1
    SERVER.daemon_threads=True
    start_update_check()
    url=f'http://127.0.0.1:{a.port}'
    print('Dominis : '+url+'\nBase : '+str(DB),flush=True)
    if a.desktop:
        try: import webview
        except ImportError: print('pywebview non installé : ouverture dans le navigateur.',flush=True)
        else:
            t=threading.Thread(target=SERVER.serve_forever,daemon=True);t.start()
            try:
                WINDOW=webview.create_window('Dominis — Gestion patrimoniale',url,width=1440,height=940,min_size=(850,650),background_color='#101211')
                WINDOW.events.closing+=on_native_closing
                webview.settings['ALLOW_DOWNLOADS']=True
                set_macos_identity()
                webview.start(signal_update_ready);SERVER.shutdown();SERVER.server_close();return 0
            except Exception as e:
                print('Fenêtre native indisponible : '+str(e));WINDOW=None
                if not a.no_browser: webbrowser.open(url)
                signal_update_ready()
                while t.is_alive():
                    try: t.join(.5)
                    except KeyboardInterrupt:
                        if UPDATE_BUSY.is_set(): continue
                        sync_exit(); SERVER.shutdown()
                SERVER.server_close()
                return 0
    if not a.no_browser and not a.preview: threading.Timer(.5,lambda:webbrowser.open(url)).start()
    signal_update_ready()
    try:
        while True:
            try: SERVER.serve_forever(); break
            except KeyboardInterrupt:
                if UPDATE_BUSY.is_set():
                    print('Mise à jour en cours : veuillez attendre le redémarrage.', flush=True)
                    continue
                sync_exit(); break
    finally: SERVER.server_close()
    return 0

if __name__=='__main__': sys.exit(run_application())
